105	    /**
106	     * Calculates the charge for a procedure. The procedure code is normalized with {@code trim()};
107	     * a {@code null} or blank code yields {@link BigDecimal#ZERO}.
108	     */
109	    public BigDecimal calculateCharge(String procedureCode, PricingContext context) {
110	        if (procedureCode == null || procedureCode.trim().isEmpty()) {
111	            log.warn("Empty procedure code provided");
112	            return BigDecimal.ZERO;
113	        }
114	        procedureCode = procedureCode.trim();
115	
116	        BigDecimal baseCharge = resolveBaseCharge(procedureCode);
117	
118	        if (baseCharge.compareTo(BigDecimal.ZERO) == 0) {
119	            log.warn("No pricing found for procedure: {}", procedureCode);
120	            return BigDecimal.ZERO;
121	        }
122	
123	        BigDecimal adjusted = applyAdjustments(procedureCode, baseCharge, context);
124	
125	        BigDecimal withDiscounts = applyDiscounts(procedureCode, adjusted, context);
126	
127	        BigDecimal withSurcharges = applySurcharges(procedureCode, withDiscounts, context);
128	
129	        BigDecimal withTax = applyTax(procedureCode, withSurcharges, context);
130	
131	        BigDecimal rounded = roundToNearestCent(withTax);
132	
133	        BigDecimal final_amount = applyLegacyScript(procedureCode, rounded, context);
134	
135	        log.debug("Calculated charge for {}: {} -> {} -> {} -> {} -> {} -> {}",
136	                procedureCode, baseCharge, adjusted, withDiscounts, withSurcharges, withTax, final_amount);
137	
138	        return final_amount;
139	    }
140	
141	    private BigDecimal resolveBaseCharge(String procedureCode) {
142	        if (LEGACY_PRICING_TABLE.containsKey(procedureCode)) {
143	            return LEGACY_PRICING_TABLE.get(procedureCode);
144	        }
145	
146	        Optional<Procedure> procedure = procedureRepository.findByProcedureCode(procedureCode);
147	        if (procedure.isPresent()) {
148	            BigDecimal cost = procedure.get().getDefaultCost();
149	            if (cost != null && cost.compareTo(BigDecimal.ZERO) > 0) {
150	                return cost;
151	            }
152	        }
153	
154	        if (procedureCode.startsWith("XR")) {
155	            return new BigDecimal("125.00");
156	        } else if (procedureCode.startsWith("LAB")) {
157	            return new BigDecimal("45.00");
158	        } else if (procedureCode.startsWith("TEL")) {
159	            return new BigDecimal("75.00");
160	        } else if (procedureCode.startsWith("PROC")) {
161	            return new BigDecimal("150.00");
162	        } else if (procedureCode.startsWith("992")) {
163	            return new BigDecimal("110.00");
164	        }
165	
166	        return new BigDecimal("50.00");
167	    }
168	
169	    private BigDecimal applyAdjustments(String procedureCode, BigDecimal base, PricingContext context) {
170	        String family = PROCEDURE_FAMILIES.get(procedureCode);
171	        if (family == null) {
172	            family = deriveFamilyFromCode(procedureCode);
173	        }
174	
175	        BigDecimal adjusted = base;
176	
177	        switch (family) {
178	            case "OFFICE_VISIT_NEW":
179	                if (Boolean.TRUE.equals(context.isFirstVisit())) {
180	                    adjusted = adjusted.multiply(new BigDecimal("1.15"));
181	                }
182	                if (context.getComplexityLevel() != null) {
183	                    switch (context.getComplexityLevel()) {
184	                        case "LOW":
185	                            adjusted = adjusted.multiply(new BigDecimal("0.90"));
186	                            break;
187	                        case "MODERATE":
188	                            break;
189	                        case "HIGH":
190	                            adjusted = adjusted.multiply(new BigDecimal("1.20"));
191	                            break;
192	                        case "VERY_HIGH":
193	                            adjusted = adjusted.multiply(new BigDecimal("1.40"));
194	                            break;
195	                    }
196	                }
197	                break;
198	
199	            case "OFFICE_VISIT_ESTABLISHED":
200	                if (context.getTimeSinceLastVisit() != null) {
201	                    int daysSince = context.getTimeSinceLastVisit();
202	                    if (daysSince < 30) {
203	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
204	                    } else if (daysSince > 365) {
205	                        adjusted = adjusted.multiply(new BigDecimal("1.10"));
206	                    }
207	                }
208	                if (context.getComplexityLevel() != null) {
209	                    switch (context.getComplexityLevel()) {
210	                        case "LOW":
211	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
212	                            break;
213	                        case "MODERATE":
214	                            break;
215	                        case "HIGH":
216	                            adjusted = adjusted.multiply(new BigDecimal("1.25"));
217	                            break;
218	                        case "VERY_HIGH":
219	                            adjusted = adjusted.multiply(new BigDecimal("1.50"));
220	                            break;
221	                    }
222	                }
223	                break;
224	
225	            case "RADIOLOGY":
226	                if (Boolean.TRUE.equals(context.isPortable())) {
227	                    adjusted = adjusted.multiply(new BigDecimal("1.30"));
228	                }
229	                if (Boolean.TRUE.equals(context.isWithContrast())) {
230	                    adjusted = adjusted.multiply(new BigDecimal("1.45"));
231	                }
232	                if (context.getNumberOfViews() != null) {
233	                    int views = context.getNumberOfViews();
234	                    if (views == 1) {
235	                        adjusted = adjusted.multiply(new BigDecimal("0.80"));
236	                    } else if (views == 2) {
237	                    } else if (views >= 3) {
238	                        adjusted = adjusted.multiply(new BigDecimal("1.20"));
239	                    }
240	                }
241	                if (Boolean.TRUE.equals(context.isStatOrder())) {
242	                    adjusted = adjusted.multiply(new BigDecimal("1.35"));
243	                }
244	                break;
245	
246	            case "LABORATORY":
247	                if (Boolean.TRUE.equals(context.isStatOrder())) {
248	                    adjusted = adjusted.multiply(new BigDecimal("1.40"));
249	                }
250	                if (Boolean.TRUE.equals(context.isFastingRequired()) && Boolean.TRUE.equals(context.isFastingCompleted())) {
251	                    adjusted = adjusted.multiply(new BigDecimal("1.05"));
252	                }
253	                if (context.getLabPanelSize() != null) {
254	                    int panelSize = context.getLabPanelSize();
255	                    if (panelSize >= 5) {
256	                        adjusted = adjusted.multiply(new BigDecimal("0.90"));
257	                    } else if (panelSize >= 10) {
258	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
259	                    }
260	                }
261	                break;
262	
263	            case "TELEHEALTH":
264	                if (context.getTelehealthPlatform() != null) {
265	                    switch (context.getTelehealthPlatform()) {
266	                        case "VIDEO":
267	                            break;
268	                        case "PHONE":
269	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
270	                            break;
271	                        case "CHAT":
272	                            adjusted = adjusted.multiply(new BigDecimal("0.70"));
273	                            break;
274	                    }
275	                }
276	                if (context.getDuration() != null) {
277	                    int minutes = context.getDuration();
278	                    if (minutes < 15) {
279	                        adjusted = adjusted.multiply(new BigDecimal("0.75"));
280	                    } else if (minutes > 45) {
281	                        adjusted = adjusted.multiply(new BigDecimal("1.25"));
282	                    } else if (minutes > 60) {
283	                        adjusted = adjusted.multiply(new BigDecimal("1.50"));
284	                    }
285	                }
286	                break;
287	
288	            case "PROCEDURE":
289	                if (Boolean.TRUE.equals(context.requiresSedation())) {
290	                    adjusted = adjusted.multiply(new BigDecimal("1.40"));
291	                }
292	                if (Boolean.TRUE.equals(context.requiresAssistant())) {
293	                    adjusted = adjusted.multiply(new BigDecimal("1.20"));
294	                }
295	                if (context.getAnesthesiaType() != null) {
296	                    switch (context.getAnesthesiaType()) {
297	                        case "LOCAL":
298	                            adjusted = adjusted.multiply(new BigDecimal("1.10"));
299	                            break;
300	                        case "REGIONAL":
301	                            adjusted = adjusted.multiply(new BigDecimal("1.30"));
302	                            break;
303	                        case "GENERAL":
304	                            adjusted = adjusted.multiply(new BigDecimal("1.60"));
305	                            break;
306	                    }
307	                }
308	                break;
309	
310	            default:
311	                log.debug("No specific adjustments for family: {}", family);
312	        }
313	
314	        return adjusted;
315	    }
316	
317	    private BigDecimal applyDiscounts(String procedureCode, BigDecimal amount, PricingContext context) {
318	        BigDecimal discounted = amount;
319	
320	        if (context.getPatientAge() != null && context.getPatientAge() >= 65) {
321	            BigDecimal seniorDiscount = DISCOUNT_RULES.get("SENIOR");
322	            if (seniorDiscount != null) {
323	                discounted = discounted.multiply(seniorDiscount);
324	            }
325	        }
326	
327	        if (Boolean.TRUE.equals(context.isEmployeeDependent())) {
328	            BigDecimal employeeDiscount = DISCOUNT_RULES.get("EMPLOYEE");
329	            if (employeeDiscount != null) {
330	                discounted = discounted.multiply(employeeDiscount);
331	            }
332	        }
333	
334	        if (Boolean.TRUE.equals(context.isSelfPay())) {
335	            BigDecimal selfPayDiscount = DISCOUNT_RULES.get("SELF_PAY");
336	            if (selfPayDiscount != null) {
337	                discounted = discounted.multiply(selfPayDiscount);
338	            }
339	        }
340	
341	        if (Boolean.TRUE.equals(context.hasContractedInsurance())) {
342	            BigDecimal insuranceDiscount = DISCOUNT_RULES.get("INSURANCE_CONTRACTED");
343	            if (insuranceDiscount != null) {
344	                discounted = discounted.multiply(insuranceDiscount);
345	            }
346	        }
347	
348	        String family = PROCEDURE_FAMILIES.get(procedureCode);
349	        if ("LABORATORY".equals(family) && context.getLabPanelSize() != null && context.getLabPanelSize() >= 5) {
350	            BigDecimal bulkDiscount = DISCOUNT_RULES.get("BULK_LAB");
351	            if (bulkDiscount != null) {
352	                discounted = discounted.multiply(bulkDiscount);
353	            }
354	        }
355	
356	        if (context.getCustomDiscountPercent() != null) {
357	            BigDecimal customDiscount = BigDecimal.ONE.subtract(
358	                    context.getCustomDiscountPercent().divide(new BigDecimal("100"), 4, RoundingMode.HALF_UP)
359	            );
360	            discounted = discounted.multiply(customDiscount);
361	        }
362	
363	        return discounted;
364	    }
365	
366	    private BigDecimal applySurcharges(String procedureCode, BigDecimal amount, PricingContext context) {
367	        BigDecimal surcharged = amount;
368	
369	        if (context.getServiceDateTime() != null) {
370	            ZonedDateTime serviceTime = context.getServiceDateTime();
371	            int hour = serviceTime.getHour();
372	            DayOfWeek dayOfWeek = serviceTime.getDayOfWeek();
373	
374	            if (hour < 7 || hour > 18) {
